using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

namespace RogControl {
 public partial class MainWindow {
  readonly List<Dictionary<string,object>> receiverStates=new List<Dictionary<string,object>>();
  string receiverMessage="尚未读取接收器。";
  string receiverTab="接收器",selectedReceiverId="";
  void OriginalReceiverPage(){
   var state=receiverStates.FirstOrDefault(v=>OriginalStateText(v,"deviceId","")==selectedReceiverId)??receiverStates.FirstOrDefault(v=>OriginalStateText(v,"pid","")=="6862")??receiverStates.FirstOrDefault();string receiverTitle=OriginalStateText(state,"pid","")=="6864"?"ROG SPEEDNOVA 8K RECEIVER":OriginalStateText(state,"pid","")=="7508"?"ROG 接收器":"ROG OMNI 接收器";var title=Label(receiverTitle,24,text,FontWeights.SemiBold);title.Margin=new Thickness(14,0,0,23);var top=new Grid();top.ColumnDefinitions.Add(new ColumnDefinition());top.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});top.Children.Add(title);if(receiverStates.Count>1){var selector=MousePerformanceCombo(new string[0],-1,!busy&&!closing&&!render,300);foreach(var candidate in receiverStates){var item=new ComboBoxItem{Content=OriginalStateText(candidate,"product",OriginalStateText(candidate,"model","ROG 接收器")),Tag=OriginalStateText(candidate,"deviceId","")};selector.Items.Add(item);if(Object.ReferenceEquals(candidate,state))selector.SelectedItem=item;}selector.SelectionChanged+=(s,e)=>{var item=selector.SelectedItem as ComboBoxItem;if(item==null||render||busy||closing)return;selectedReceiverId=Convert.ToString(item.Tag);ShowPage(page);};Grid.SetColumn(selector,1);top.Children.Add(selector);}content.Children.Add(top);var tabs=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(18,0,0,0)};foreach(string name in new[]{"接收器","固件更新"}){string chosen=name;var tab=Button(name,()=>{receiverTab=chosen;ShowPage(page);});tab.Width=180;tab.Height=42;tab.Margin=new Thickness(0);tab.Padding=new Thickness(8);tab.Background=name==receiverTab?Brush("#211E16"):Brushes.Transparent;tab.BorderThickness=new Thickness(0,0,0,name==receiverTab?2:0);tab.BorderBrush=accent;tabs.Children.Add(tab);}content.Children.Add(tabs);PinPageHeader(2,"receiver:"+receiverTab);
   bool known=state!=null&&GearOnline(state)&&OriginalStateFlag(state,"readbackConfirmed")==true;var snapshot=known?GearMap(state,"snapshot"):null;var surface=new StackPanel{Width=920,Margin=new Thickness(162,28,0,0),HorizontalAlignment=HorizontalAlignment.Left};var viewport=new ScrollViewer{Content=surface,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled};content.Children.Add(viewport);
   if(receiverTab=="固件更新"){var firmware=Label("当前固件版本："+OriginalStateText(snapshot,"firmware","—"),16,text);firmware.TextAlignment=TextAlignment.Center;firmware.Margin=new Thickness(0,100,0,36);surface.Children.Add(firmware);var check=Button("检查更新",()=>{});check.IsEnabled=false;check.ToolTip="接收器固件更新暂不可用";ToolTipService.SetShowOnDisabled(check,true);check.HorizontalAlignment=HorizontalAlignment.Center;surface.Children.Add(check);return;}
   var header=new Grid();header.ColumnDefinitions.Add(new ColumnDefinition());header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var heading=Label("已配对设备",16,text,FontWeights.SemiBold);heading.Margin=new Thickness(0,0,0,18);header.Children.Add(heading);var refresh=Button("↻",async()=>await ReadOriginalReceivers());refresh.Width=32;refresh.Height=28;refresh.Padding=new Thickness(0);refresh.Margin=new Thickness(0);refresh.Background=Brushes.Transparent;refresh.BorderThickness=new Thickness(0);refresh.IsEnabled=!busy&&!render&&!closing;refresh.ToolTip="读取接收器";Grid.SetColumn(refresh,1);header.Children.Add(refresh);surface.Children.Add(header);var note=Paragraph("若设备显示已配对但无法使用，请先确认设备已被唤醒并切换为 RF 2.4GHz 模式。",13,muted);note.Margin=new Thickness(0,0,0,46);surface.Children.Add(note);
   var cards=new Grid{Margin=new Thickness(172,0,170,22)};cards.ColumnDefinitions.Add(new ColumnDefinition());cards.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(80)});cards.ColumnDefinitions.Add(new ColumnDefinition());var pairs=GearArray(snapshot,"pairedDevices");for(int i=0;i<2;i++){string kind=i==0?"keyboard":"mouse";var pair=pairs==null?null:pairs.OfType<Dictionary<string,object>>().FirstOrDefault(v=>OriginalStateText(v,"kind","")==kind);var card=ReceiverPairCard(kind,pair,known&&pairs!=null&&pairs.All(raw=>raw is Dictionary<string,object>&&new[]{"keyboard","mouse"}.Contains(OriginalStateText((Dictionary<string,object>)raw,"kind",""))));Grid.SetColumn(card,i*2);cards.Children.Add(card);}surface.Children.Add(cards);
   var reset=Button("重置与配对",()=>{});reset.IsEnabled=false;reset.Width=136;reset.Height=34;reset.Padding=new Thickness(8);reset.Margin=new Thickness(230,0,0,30);reset.HorizontalAlignment=HorizontalAlignment.Left;reset.ToolTip="配对设置暂不可用";ToolTipService.SetShowOnDisabled(reset,true);surface.Children.Add(reset);surface.Children.Add(new Border{Height=1,Background=border,Margin=new Thickness(0,0,0,36)});surface.Children.Add(Label("新增配对设备",16,text,FontWeights.SemiBold));var add=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,32,0,0)};foreach(string kind in new[]{"mouse","keyboard"}){var body=new StackPanel{Width=100};body.Children.Add(ReceiverDeviceIcon(kind));var caption=Label(kind=="mouse"?"鼠标":"键盘",13,muted);caption.TextAlignment=TextAlignment.Center;body.Children.Add(caption);var plus=Label("⊕",23,muted);plus.TextAlignment=TextAlignment.Center;body.Children.Add(plus);add.Children.Add(new Border{Child=body,BorderBrush=border,BorderThickness=new Thickness(1,1,0,0),Padding=new Thickness(0,16,0,0),Margin=new Thickness(0,0,48,0),IsEnabled=false,ToolTip="配对设置暂不可用"});}surface.Children.Add(add);if(receiverMessage.StartsWith("读取失败",StringComparison.Ordinal)){status.Text="读取失败";status.ToolTip=receiverMessage;}
  }
  UIElement ReceiverPairCard(string kind,Dictionary<string,object> pair,bool confirmed){var body=new StackPanel{MinHeight=126};object model;bool hasModel=pair!=null&&pair.TryGetValue("model",out model)&&model is string&&!String.IsNullOrWhiteSpace((string)model)&&((string)model).Length<=180;string name=hasModel?OriginalStateText(pair,"model",""):confirmed&&pair==null?"无设备":"—";if(hasModel){body.Children.Add(ReceiverDeviceIcon(kind));var label=Label(kind=="keyboard"?"键盘":"鼠标",16,text,FontWeights.SemiBold);label.TextAlignment=TextAlignment.Center;label.Margin=new Thickness(0,16,0,10);body.Children.Add(label);}var textBlock=Label(name,13,hasModel?muted:text);textBlock.TextWrapping=TextWrapping.Wrap;textBlock.TextAlignment=TextAlignment.Center;textBlock.Margin=new Thickness(12,hasModel?0:50,12,0);body.Children.Add(textBlock);var card=new Border{Child=body,BorderBrush=border,BorderThickness=new Thickness(1),ToolTip=hasModel?"配对记录；不能据此判断设备当前在线。":null};if(hasModel)card.MouseLeftButtonUp+=(s,e)=>{if(!render&&!closing&&!busy)OpenOriginalDevice(kind);};return card;}
  UIElement ReceiverDeviceIcon(string kind){var canvas=new Canvas{Width=44,Height=30,HorizontalAlignment=HorizontalAlignment.Center};if(kind=="mouse"){canvas.Children.Add(new Rectangle{Width=26,Height=30,RadiusX=10,RadiusY=10,Stroke=text,StrokeThickness=2,Margin=new Thickness(9,0,0,0)});canvas.Children.Add(new Line{X1=22,Y1=2,X2=22,Y2=12,Stroke=text,StrokeThickness=2});}else{canvas.Children.Add(new Rectangle{Width=44,Height=24,Stroke=text,StrokeThickness=2,Margin=new Thickness(0,3,0,0)});for(int y=0;y<2;y++)for(int x=0;x<8;x++)canvas.Children.Add(new Rectangle{Width=3,Height=3,Fill=text,Margin=new Thickness(5+x*4.5,8+y*5,0,0)});}return canvas;}
  async Task ReadOriginalReceivers(){if(busy||render||closing)return;busy=true;status.Text="正在读取接收器配对记录…";try{var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","scan"},{"kind","omni"}});if(!reply.ok)throw new InvalidOperationException(SdkError(reply.error));receiverStates.Clear();var found=GearArray(reply.data,"devices");if(found!=null)receiverStates.AddRange(found.OfType<Dictionary<string,object>>());receiverMessage="已读取 "+receiverStates.Count+" 个接收器。";Log(receiverMessage);}catch(Exception ex){receiverStates.Clear();receiverMessage="读取失败："+ex.Message;Log(receiverMessage);}finally{busy=false;if(!closing)ShowPage(page);}}
 }
}
